{
  "technical_and_design_decisions": [
    "Kafka and Rabbit test rules will be extracted into standalone Maven/Gradle repositories and published as test-support artifacts.",
    "The SCDF Admin REST API abstraction will rely on a unified SPI abstraction layer over platform-specific deployers (Cloud Foundry, YARN, Lattice).",
    "Stream DSL parser will be extended to parse named channel syntax (e.g., '> :channel-name' and ':channel-name >') without requiring source or sink app bindings.",
    "StreamController tests will utilize Spring MVC Test Framework (MockMvc) to verify REST endpoints, request parameters, and HTTP response codes.",
    "Unique stream name validation will be enforced at both the service layer and database/repository constraint layer, throwing a specific ConflictException mapped to HTTP 409 Conflict.",
    "The Kinesis source module will leverage AWS Kinesis Client Library (KCL) integrated with Spring Integration and Spring Cloud Stream Binder abstraction."
  ],
  "assumptions": [
    "Development environment uses Java 17+ and Spring Boot / Spring Framework 6.x aligned with SCDF baseline.",
    "CI/CD infrastructure is already available for creating and publishing new Git repositories for test rules.",
    "Target platforms (Cloud Foundry, YARN, Lattice) deployer implementations exist or have established SPI interfaces to bind against.",
    "All work is performed by a single experienced senior software developer."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Extract Kafka Test Rule to Separate Repository",
      "activity_description": "Extract Kafka JUnit test rule and fixtures into a dedicated repository, configure build scripts, setup publication pipeline, and update main project dependencies (U1).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Extract Rabbit Test Rule to Separate Repository",
      "activity_description": "Extract RabbitMQ JUnit test rule and fixtures into a separate repository, configure build automation, publish artifacts, and update s-c-d project references (U2).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Standardize Admin REST APIs across Deployer Platforms",
      "activity_description": "Design and implement unified REST API endpoint handlers and platform abstraction layer for Admin server across Lattice, YARN, and Cloud Foundry deployers (U3).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Implement Artifact Library Registration and Include/Exclude Directives",
      "activity_description": "Extend App Registry model and REST controller to register library artifacts, and update dependency resolution logic for include/exclude directives (U4).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Implement Named Channels Support in Stream DSL and Runtime",
      "activity_description": "Update Stream DSL grammar, parser, and deployment engine to support named channels for stream pipelines without dedicated source or sink modules (U5).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Add Test Coverage for StreamController",
      "activity_description": "Develop comprehensive MockMvc test suite for StreamController to verify API contracts, payload validation, success responses, and error handling at build time (U6).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Implement Unique Stream Name Validation",
      "activity_description": "Add stream name uniqueness check in StreamDefinitionService and repository layer, returning appropriate error response when duplicate names are submitted (U7).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Develop Kinesis Source Module for Spring Cloud Stream",
      "activity_description": "Implement Kinesis source module using Spring Integration / KCL, add configuration properties, auto-configuration, and integration test coverage (U8).",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration Testing and End-to-End Verification",
      "activity_description": "Perform full integration testing of stream lifecycle, platform REST APIs, named channels, and library registration across the system.",
      "most_likely_effort": 18
    }
  ],
  "reported_total": {
    "most_likely_effort": 170
  }
}
